-- 1. Buat Tabel academic_records
CREATE TABLE IF NOT EXISTS `academic_records` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `category` ENUM('publikasi', 'riset', 'pengabdian', 'hki', 'buku') NOT NULL DEFAULT 'publikasi',
  `subcategory` VARCHAR(100) NULL DEFAULT NULL,
  `title` TEXT NOT NULL,
  `authors` TEXT NULL,
  `journal_meta` TEXT NULL,
  `url` TEXT NULL,
  `year` VARCHAR(10) NULL,
  `sort_order` INT NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  INDEX `idx_category_active` (`category`, `is_active`),
  INDEX `idx_sort_order` (`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Kosongkan data lama jika ingin me-refresh ulang
TRUNCATE TABLE `academic_records`;

